update public.cms_sections set data=jsonb_set(jsonb_set(jsonb_set(data,'{logos}',(select jsonb_agg(jsonb_set(value,'{src}','null') order by ordinal) from jsonb_array_elements(data->'logos') with ordinality as x(value,ordinal))),'{logos,0,name}','"Admin edited Shell name"'),'{heading}','"Admin edited trust heading"'),enabled=false,revision=30 where page_id='home' and key='sectionTwo';
